			// state_ij contains indices (i, j)
			C[state_ij] *= beta;
		});
	});

	// -------------------------------------------------------------------------
	// 2) Rank-2k update:
	//
	//    for (i = 0; i < N; i++)
	//      for (k = 0; k < M; k++) {
	//        const auto Aik = A[i][k];
	//        const auto Bik = B[i][k];
