// A: i x k  (N x M)
// B: i x k  (N x M)
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Precompute lengths once instead of inside the loops
	const auto n_len_A = A | get_length<'i'>(); // corresponds to original 'n'
	const auto m_len_B = B | get_length<'k'>(); // corresponds to original 'm'
	const auto n_len_C = C | get_length<'i'>(); // N
	const auto m_len_C = m_len_B;              // M (same as for B)

	// Initialize A: A[i][k] = ( (i * k + 1) % n ) / n
	traverser(A).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len_A) / n_len_A;
	});

	// Initialize B: B[i][k] = ( (i * k + 2) % m ) / m
	traverser(B).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		B[state] = (num_t)((i * k + 2) % m_len_B) / m_len_B;
	});

	// Initialize C: C[i][j] = ( (i * j + 3) % n ) / m
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 3) % n_len_C) / m_len_C;
	});
}

// computation kernel
// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k
	// B: i x k

#pragma scop
	// -------------------------------------------------------------------------
	// 1) Scale the lower-triangular part of C by beta.
	//
	//    We traverse only C here (no need to involve A or B), which avoids
	//    unnecessary iteration over the 'k' dimension present in A/B.
	// -------------------------------------------------------------------------
	traverser(C).template for_dims<'i'>([&](auto trav_i) {
		const auto state_i = trav_i.state();
		const auto i_idx   = get_index<'i'>(state_i);

		// Iterate all j for the fixed i; only update j <= i.
		trav_i.for_each([&](auto state_ij) {
			const auto j_idx = get_index<'j'>(state_ij);

			if (j_idx <= i_idx) {
				C[state_ij] *= beta;
			}
		});
	});

