	//        for j in 0..i
	//          C[i][j] += alpha * (A[j][k] * B_ik + B[j][k] * A_ik)
	//
	//    Optimizations:
	//      * Traverse using Noarr traversers over (C, A, B).
	//      * For each fixed (i,k) we load A[i][k] and B[i][k] once and
	//        precompute alpha*A_ik and alpha*B_ik. These are reused for all j.
	//      * The arithmetic is reorganized to:
	//            C += A_jk * (alpha * B_ik) + B_jk * (alpha * A_ik)
	//        which reduces the number of multiplications in the inner loop.
	// -------------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		const auto state_i = trav_i.state();
		const auto i_idx   = get_index<'i'>(state_i);

		// Outer loop over k for the current row i
		trav_i.template for_dims<'k'>([&](auto trav_k) {
			// state_ik has indices (i, k) fixed, no j yet
			const auto state_ik = trav_k.state();
			const auto k_idx    = get_index<'k'>(state_ik);

			// Load A[i][k] and B[i][k] once per (i,k)
			const num_t A_ik = A[state_ik];
			const num_t B_ik = B[state_ik];

			// Precompute products with alpha once per (i,k)
			const num_t alphaA_ik = alpha * A_ik;
			const num_t alphaB_ik = alpha * B_ik;

			// Inner loop over j for fixed (i,k).
			// trav_k.for_each iterates the remaining dimension(s), i.e., 'j'.
			trav_k.for_each([&](auto state) {
				const auto j_idx = get_index<'j'>(state);

				// We only update the lower-triangular part j <= i
				if (j_idx <= i_idx) {
					// Build the state (i=j, k) for A and B.
					// We start from state_ik (which has 'i' and 'k') and
					// replace the 'i' index by j_idx.
					auto state_jk = state_ik.template with<index_in<'i'>>(j_idx);

					const num_t A_jk = A[state_jk];
					const num_t B_jk = B[state_jk];

					// C[i][j] += alpha * (A_jk * B_ik + B_jk * A_ik)
					//          = A_jk * (alpha * B_ik) + B_jk * (alpha * A_ik)
					C[state] += A_jk * alphaB_ik + B_jk * alphaA_ik;
				}
			});
		});
	});
