	const num_t inv_n = num_t(1) / num_t(n_len);
	const num_t inv_m = num_t(1) / num_t(m_len);

	// ---------------------------------------------------------------------
	// Initialize A: A[i][k] = ( (i * k + 1) % n ) / n
	// ---------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		const std::size_t val = (i * k + 1) % n_len;
		A[state] = num_t(val) * inv_n;
	});

	// ---------------------------------------------------------------------
	// Initialize B: B[i][k] = ( (i * k + 2) % m ) / m
	// ---------------------------------------------------------------------
