// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
//
// The kernel is written entirely using Noarr traversers. The traversal
// order is chosen to improve locality and reduce redundant computation:
//
// 1) Scale the lower triangle of C by beta.
// 2) For each (i, k), pre-load A[i][k] and B[i][k] and hoist
//    the products alpha*A[i][k] and alpha*B[i][k] out of the j-loop.
//    Then iterate over j and update C[i][j] for j <= i.
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k
	// B: i x k

#pragma scop
	// ---------------------------------------------------------------------
	// 1) Scale C's lower-triangular part: C[i][j] *= beta  for j <= i
	// ---------------------------------------------------------------------
