		const auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		trav_i.for_each([&](auto state_ij) {
			const std::size_t j_idx = get_index<'j'>(state_ij);

			if (j_idx <= i_idx) {
				C[state_ij] *= beta;
			}
		});
	});

	// ---------------------------------------------------------------------
	// 2) Rank-2k update:
	//      for i in 0..N-1
	//        for k in 0..M-1
	//          let Aik = A[i][k], Bik = B[i][k]
	//          for j in 0..i
	//            C[i][j] += alpha*Aik*B[j][k] + alpha*Bik*A[j][k]
	// ---------------------------------------------------------------------
	traverser(A, B, C).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, iterates over 'k' and 'j'
		const auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// Loop over k with 'i' fixed
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has both 'i' and 'k' fixed, iterates over 'j'
			const auto state_ik = trav_ik.state();
			const std::size_t k_idx = get_index<'k'>(state_ik);

			// Load A[i][k] and B[i][k] once per (i, k)
			const num_t A_ik = A[state_ik];
			const num_t B_ik = B[state_ik];

			// Hoist multiplications by alpha out of the j-loop
			const num_t alphaA_ik = alpha * A_ik;
			const num_t alphaB_ik = alpha * B_ik;

			// Now iterate over j (all j, but only update when j <= i)
			trav_ik.for_each([&](auto state_ijk) {
				const std::size_t j_idx = get_index<'j'>(state_ijk);

				if (j_idx <= i_idx) {
					// Build a state for (j, k) to read A[j][k] and B[j][k].
					// We only need dimensions 'i' and 'k' for A/B, so a fresh
					// state keeps the operation simple and layout-agnostic.
					auto state_jk = noarr::idx<'i', 'k'>(j_idx, k_idx);

					const num_t A_jk = A[state_jk];
					const num_t B_jk = B[state_jk];

					// C[i][j] update:
					//   C[i][j] += alpha*A[i][k]*B[j][k] + alpha*B[i][k]*A[j][k]
					// We use the hoisted products to save two multiplications.
					C[state_ijk] += alphaA_ik * B_jk + alphaB_ik * A_jk;
